#!/usr/bin/env python3
"""Archer · the one assistant model: the complete pipeline in a single file.

Generated from training/cree_llm/cells/*.py by build_trainer.py. Edit the cells
and rebuild; do not edit this file.

Stages, in order
----------------
  corpus     download, verify and ledger every Cree source
  clean      normalise, deduplicate, split by document, guard against leakage
  tokenizer  Cree-aware SentencePiece vocabulary grafted onto the base model
  cpt        continued pretraining on running Cree text, with English replay
  sft        instruction tuning: conversation, song notes, translation,
             syllabics and word explanation, for one model
  dpo        preference tuning for faithfulness
  eval       CreeBench: base against tuned, both directions, chrF++ / BLEU /
             token F1 / validity / code-switch / perplexity
  report     report card, figures, model card and data card
  export     merge the adapter, build GGUF, write the Ollama Modelfile, zip

Run it
------
  python -m pip install -r training/requirements-cree.txt   # once, with the
                                                           # torch build that
                                                           # matches your CUDA
  python train_cree_llm.py --check
  python train_cree_llm.py --profile a100 --work /data/cree_llm

Training runs on one GPU. On a multi-GPU box it takes the card with the most
free memory, so another job on device 0 does not become an out-of-memory
traceback. --gpu N pins a card, and CUDA_VISIBLE_DEVICES is respected when it
is already set.

Resuming is automatic. Every stage records a fingerprint of its inputs in
<work>/run_state.json: a finished stage is skipped, and an interrupted training
stage continues from its newest checkpoint-N. Re-run the same command after a
crash, a reboot or a closed terminal.

Everything is written under --work: raw/, processed/, checkpoints/, out/, logs/.
No file is read from this repository, so this file works on a server on its own.
"""

from __future__ import annotations

import argparse
import importlib
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

STAGES = ("corpus", "clean", "tokenizer", "cpt", "sft", "dpo", "eval", "report", "export")
TRAINED = ("cpt", "sft", "dpo", "eval", "llmtests")
STARTED = time.time()

REQUIRED = (
    ("torch", "torch"),
    ("transformers", "transformers>=4.46,<6"),
    ("peft", "peft>=0.13"),
    ("datasets", "datasets>=3"),
    ("accelerate", "accelerate>=1.0"),
    ("bitsandbytes", "bitsandbytes>=0.44"),
    ("sentencepiece", "sentencepiece>=0.2"),
    ("sacrebleu", "sacrebleu>=2.4"),
    ("matplotlib", "matplotlib>=3.8"),
    ("pandas", "pandas>=2.0"),
    ("psutil", "psutil>=5.9"),
)


class _Tee:
    """Write to the terminal and to a log file at the same time."""

    def __init__(self, *streams):
        self.streams = [s for s in streams if s is not None]

    def write(self, data):
        for stream in self.streams:
            stream.write(data)
            stream.flush()
        return len(data)

    def flush(self):
        for stream in self.streams:
            stream.flush()

    def isatty(self) -> bool:
        return False


def _work_dir(args) -> Path:
    raw = args.work or os.environ.get("CREE_WORK") or "cree_llm_work"
    return Path(raw).expanduser().resolve()


def _gpu_inventory() -> list[dict]:
    """Every card with its free memory, as nvidia-smi reports it.

    Read before torch is imported. A CUDA context allocates a few hundred
    megabytes on the default card, and torch cannot see another user's process
    at all; nvidia-smi can, which is the whole point here.
    """
    try:
        out = subprocess.run(
            ["nvidia-smi", "--query-gpu=index,name,memory.total,memory.free",
             "--format=csv,noheader,nounits"],
            capture_output=True, text=True, timeout=15,
        )
    except (OSError, subprocess.SubprocessError):
        return []
    if out.returncode != 0:
        return []
    cards: list[dict] = []
    for line in out.stdout.splitlines():
        parts = [part.strip() for part in line.split(",")]
        if len(parts) < 4:
            continue
        try:
            cards.append({
                "index": int(parts[0]),
                "name": parts[1],
                "total_mib": float(parts[2]),
                "free_mib": float(parts[3]),
            })
        except ValueError:
            continue
    return cards


# A 7B load in nf4 needs room for transformers' warmup allocation plus the
# quantised weights. Below this, the load itself is what fails.
GPU_LOAD_GB = 8.0


def _select_gpu(args) -> None:
    """Pin the run to a card that is actually free.

    CUDA defaults to device 0, and on a shared box device 0 is often busy. The
    failure then arrives from inside transformers as a five-gigabyte allocation
    during caching_allocator_warmup, which never mentions the other process.
    Choosing by free memory keeps the run alive; logging the choice makes it
    visible.
    """
    if args.gpu is not None:
        os.environ["CUDA_VISIBLE_DEVICES"] = str(args.gpu)
        print(f"gpu:     device {args.gpu} (from --gpu)", flush=True)
        return
    if os.environ.get("CUDA_VISIBLE_DEVICES"):
        print(f"gpu:     CUDA_VISIBLE_DEVICES={os.environ['CUDA_VISIBLE_DEVICES']} kept as set",
              flush=True)
        return
    cards = _gpu_inventory()
    if not cards:
        return
    best = max(cards, key=lambda card: card["free_mib"])
    note = ""
    if best["index"] != 0:
        os.environ["CUDA_VISIBLE_DEVICES"] = str(best["index"])
        note = f"device 0 has {cards[0]['free_mib'] / 1024:.1f} GB free; "
    print(f"gpu:     {note}using device {best['index']} {best['name']} "
          f"({best['free_mib'] / 1024:.1f} GB free)", flush=True)
    if best["free_mib"] / 1024 < GPU_LOAD_GB:
        print(f"gpu:     warning: only {best['free_mib'] / 1024:.1f} GB free and a "
              f"7B load needs about {GPU_LOAD_GB:.0f} GB. Free a card or pass --gpu N.",
              flush=True)


def _parse_args(argv: list[str] | None = None):
    ap = argparse.ArgumentParser(
        prog="train_cree_llm.py",
        description="Train, evaluate and export the one Archer assistant model.",
    )
    ap.add_argument("--work", metavar="DIR",
                    help="where corpora, checkpoints and outputs live (default ./cree_llm_work)")
    ap.add_argument("--profile", choices=("auto", "smoke", "t4", "a100", "big24", "big", "huge"),
                    help="hardware preset: t4 16 GB 3B, big24 24 GB 14B, a100 40 GB 7B, "
                         "big/huge 80 GB 14B/32B; auto picks the largest base that fits")
    ap.add_argument("--gpu", type=int, metavar="N",
                    help="CUDA card to train on (default: the one with the most free memory)")
    ap.add_argument("--base-model", metavar="MODEL",
                    help="Hugging Face base model; overrides the profile's choice")
    ap.add_argument("--seq-len", type=int, help="training context length in tokens")
    ap.add_argument("--lora-r", type=int, help="LoRA rank")
    ap.add_argument("--cpt-epochs", type=float, help="continued pretraining passes")
    ap.add_argument("--sft-epochs", type=float, help="instruction tuning passes")
    ap.add_argument("--dpo-epochs", type=float, help="preference tuning passes; 0 disables it")
    ap.add_argument("--eval-n", type=int, help="held-out pairs scored by CreeBench")
    ap.add_argument("--save-minutes", type=float, help="checkpoint interval during training")
    ap.add_argument("--hf-home", metavar="DIR", help="cache for base weights (default <work>/hf)")
    ap.add_argument("--uploads", metavar="DIR",
                    help="folder of .txt/.md Cree text to add to the corpus (default <work>/uploads)")
    ap.add_argument("--external-model", metavar="TAG",
                    help="Ollama tag to score on the same CreeBench prompts, for comparison")
    ap.add_argument("--ollama-url", metavar="URL",
                    help="Ollama endpoint for --external-model (default http://127.0.0.1:11434)")
    ap.add_argument("--merge-device", choices=("auto", "cpu", "cuda"),
                    help="where the export merges the adapter, if it does not auto-fit")
    ap.add_argument("--to", choices=STAGES, metavar="STAGE",
                    help="stop after this stage instead of running to the export")
    ap.add_argument("--force", metavar="STAGE[,STAGE]",
                    help="run these stages again even though they are marked finished")
    ap.add_argument("--log-file", metavar="PATH", help="where the run log is written")
    ap.add_argument("--no-log", action="store_true", help="do not write a log file")
    ap.add_argument("--check", action="store_true",
                    help="verify the environment and exit without training")
    args = ap.parse_args(argv)

    if args.force:
        names = [name.strip().lower() for name in args.force.split(",") if name.strip()]
        unknown = [name for name in names if name not in STAGES]
        if unknown:
            ap.error(f"unknown stage(s) in --force: {', '.join(unknown)}. "
                     f"Choose from {', '.join(STAGES)}.")
        # A retrained stage invalidates every stage built on it. Forcing CPT and
        # leaving SFT marked finished would otherwise stop the run at CPT and
        # still report success.
        expanded = set(names)
        for name in names:
            if name in TRAINED:
                expanded.update(TRAINED[TRAINED.index(name):])
        args.expanded = sorted(expanded - set(names))
        args.force = ",".join(sorted(expanded))
    return args


def _preflight(args) -> int:
    print(f"python  {sys.version.split()[0]}  ({sys.platform})")
    missing: list[str] = []
    for module, spec in REQUIRED:
        try:
            print(f"  ok    {module:16s} {getattr(importlib.import_module(module), '__version__', '?')}")
        except Exception as exc:
            print(f"  MISS  {module:16s} {type(exc).__name__}: {exc}")
            missing.append(spec)

    try:
        import torch

        print(f"\ntorch   {torch.__version__}  cuda={torch.version.cuda}")
        if torch.cuda.is_available():
            # Free memory is only attributable to these indices when the run
            # sees every card. With CUDA_VISIBLE_DEVICES set, torch renumbers
            # the visible subset and nvidia-smi's indices no longer line up.
            visible = os.environ.get("CUDA_VISIBLE_DEVICES")
            inventory = {} if visible else {c["index"]: c for c in _gpu_inventory()}
            for i in range(torch.cuda.device_count()):
                props = torch.cuda.get_device_properties(i)
                line = f"gpu {i}   {props.name}  {props.total_memory / 1024 ** 3:.1f} GB"
                card = inventory.get(i)
                if card:
                    line += f"  {card['free_mib'] / 1024:5.1f} GB free"
                    if card["free_mib"] / 1024 < GPU_LOAD_GB:
                        line += "  in use"
                print(line)
            print(f"bf16    {torch.cuda.is_bf16_supported()}")
            if inventory:
                best = max(inventory.values(), key=lambda card: card["free_mib"])
                print(f"pick    device {best['index']}  ({best['free_mib'] / 1024:.1f} GB free); "
                      f"training uses it unless --gpu N says otherwise")
        else:
            print("gpu     none visible; set CUDA_VISIBLE_DEVICES, or training will crawl on CPU")
    except Exception as exc:
        print(f"\ntorch could not be imported: {exc}")

    work = _work_dir(args)
    print(f"\nwork    {work}")
    for label, path in (("work", work), ("hf", Path(args.hf_home).expanduser() if args.hf_home else work / "hf")):
        try:
            path.mkdir(parents=True, exist_ok=True)
            print(f"disk    {shutil.disk_usage(path).free / 1024 ** 3:8.1f} GB free  {label} {path}")
        except Exception as exc:
            print(f"disk    cannot use {path}: {exc}")

    if missing:
        print("\nMissing packages. Install them, then run this again:\n")
        print("  python -m pip install " + " ".join(f'"{spec}"' for spec in missing))
        return 1
    print("\nall imports present. Run the same command without --check to start.")
    return 0


def _start_log(args):
    if args.no_log:
        return None
    path = (Path(args.log_file).expanduser() if args.log_file
            else _work_dir(args) / "logs" / f"train-{time.strftime('%Y%m%d-%H%M%S')}.log")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        handle = path.open("a", encoding="utf-8", buffering=1)
    except OSError as exc:
        print(f"[warning] cannot write a log file at {path}: {exc}")
        return None
    sys.stdout = _Tee(getattr(sys, "__stdout__", None), handle)
    sys.stderr = _Tee(getattr(sys, "__stderr__", None), handle)
    return path


def _stop_after(name: str) -> bool:
    if ARGS.to != name:
        return False
    print(f"\n[stop] reached --to {name}. Everything above is on disk; "
          f"re-run without --to to continue from here.", flush=True)
    return True


def _apply_overrides() -> None:
    """Apply command line overrides to the config the setup cell built.

    Done after the setup cell rather than before it, because the cell owns the
    presets, the memory planner and the naming. Anything derived from the base
    model is recomputed here so a 14B override cannot keep a 7B tag, and the
    four-bit decision follows the new size instead of the old one.
    """
    global MODEL_TAG, MODEL_STEM, BASE_PARAMS_B, USE_4BIT

    if ARGS.base_model:
        CFG.base_model = ARGS.base_model
    if ARGS.seq_len:
        CFG.seq_len = ARGS.seq_len
    if ARGS.lora_r:
        CFG.lora_r = ARGS.lora_r
        CFG.lora_alpha = ARGS.lora_r * 2
    if ARGS.cpt_epochs is not None:
        CFG.cpt_epochs = ARGS.cpt_epochs
    if ARGS.sft_epochs is not None:
        CFG.sft_epochs = ARGS.sft_epochs
    if ARGS.dpo_epochs is not None:
        CFG.dpo_epochs = ARGS.dpo_epochs
    if ARGS.eval_n:
        CFG.eval_n = ARGS.eval_n

    _base = CFG.base_model.lower()
    MODEL_TAG = next((tag for tag in ("32b", "14b", "7b", "3b", "1.5b", "0.5b") if tag in _base), "custom")
    MODEL_STEM = f"archer-{MODEL_TAG}"

    match = re.search(r"(\d+(?:\.\d+)?)\s*b\b", _base)
    if match:
        size = match.group(1)
        BASE_PARAMS_B = _BASE_PARAMS_B.get(f"{size}b", float(size))
    USE_4BIT = plan_weights(GPU_GB, BASE_PARAMS_B, SMOKE)

    if DEVICE == "cuda" and 0 < GPU_GB < 24 and CFG.seq_len > 1024:
        log(f"context {CFG.seq_len} does not fit {GPU_GB:.0f} GB; using 1024")
        CFG.seq_len = 1024

    if ARGS.base_model or ARGS.seq_len or ARGS.lora_r:
        log(f"overrides: base={CFG.base_model}  seq={CFG.seq_len}  LoRA r={CFG.lora_r}  "
            f"weights={'4-bit nf4' if USE_4BIT else str(DTYPE).split('.')[-1]}")


def _crash(exc_type, exc, tb) -> None:
    sys.__excepthook__(exc_type, exc, tb)
    if exc_type.__name__ == "OutOfMemoryError":
        stream = getattr(sys, "__stderr__", None) or sys.stderr
        print("\n[failed] the GPU ran out of memory during this step. Cards right now:",
              file=stream)
        cards = _gpu_inventory()
        for card in cards:
            print(f"         gpu {card['index']}  {card['name']}  "
                  f"{card['free_mib'] / 1024:.1f} of {card['total_mib'] / 1024:.1f} GB free",
                  file=stream)
        if len(cards) > 1:
            print("         another job is probably holding a card; re-run with "
                  "--gpu N to use a different one.", file=stream)
    print(
        "\n[failed] the run stopped here. Nothing above is lost: finished stages are\n"
        "         marked in run_state.json and training kept its last checkpoint.\n"
        "         Re-run the same command to continue, or add --force STAGE to redo one.\n",
        file=getattr(sys, "__stderr__", None) or sys.stderr,
    )


sys.excepthook = _crash

ARGS = _parse_args()
if ARGS.check:
    raise SystemExit(_preflight(ARGS))

if ARGS.work:
    os.environ["CREE_WORK"] = str(_work_dir(ARGS))
if ARGS.profile:
    os.environ["CREE_PROFILE"] = ARGS.profile
    # The smoke preset also shrinks the corpus and the schedules, not just the
    # model: without this flag it would download every source to prove a thing
    # that takes six packed blocks.
    if ARGS.profile == "smoke":
        os.environ["CREE_SMOKE"] = "1"
if ARGS.force:
    os.environ["CREE_FORCE"] = ARGS.force
if ARGS.save_minutes:
    os.environ["CREE_SAVE_MINUTES"] = str(ARGS.save_minutes)
if ARGS.hf_home:
    os.environ["CREE_HF_HOME"] = str(Path(ARGS.hf_home).expanduser().resolve())
if ARGS.uploads:
    os.environ["CREE_UPLOAD_DIR"] = str(Path(ARGS.uploads).expanduser().resolve())
if ARGS.external_model:
    os.environ["CREE_EXTERNAL_MODEL"] = ARGS.external_model
if ARGS.ollama_url:
    os.environ["CREE_OLLAMA_URL"] = ARGS.ollama_url
if ARGS.merge_device and ARGS.merge_device != "auto":
    os.environ["CREE_MERGE_DEVICE"] = ARGS.merge_device

# Fragmentation, not the model, is what turns a full card into "tried to allocate
# 608 MiB". Expandable segments lets PyTorch reuse a block that is otherwise
# split in two, and it costs nothing when memory is not tight.
os.environ.setdefault("PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True")
os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")

# Before torch is imported, and before the log opens, so the choice appears in
# both the terminal and the run log.
_select_gpu(ARGS)

LOG_PATH = _start_log(ARGS)
print(f"Archer model  |  {time.strftime('%Y-%m-%d %H:%M')}")
print(f"command: {' '.join(sys.argv)}")
if LOG_PATH is not None:
    print(f"log:     {LOG_PATH}")
if ARGS.to:
    print(f"stops after: {ARGS.to}")
if getattr(ARGS, "expanded", None):
    print(f"force:   also rerunning {', '.join(ARGS.expanded)}, which were built on a stage being redone")

